preConditionHook:
// LEVEL PAIR, PIVOT BREAKOUT (Brian's notes P15, TRIAGE P15, pp. 42-43).
// Non-alternating strength-2 swing highs: the 2nd and 3rd most recent sit level
// (|h2 - h3| <= eqAtr ATR, the note's "~0.05 ATR") and the most recent one
// exceeds the higher of them by at least breakAtr ATR (the note's 1 x ATR-10,
// hence atrLookback 10). LONG, on the bar the newest high is CONFIRMED
// (hb1 == strength) -- the only bar the pivot is known, so the rule fires once.
// Short mirrors on the swing lows. Not DoubleExtremeBreakout, which breaks a
// double top by ticks on any bar's extreme; here the break must itself be a
// confirmed pivot by an ATR multiple. Not SwingHighClusterDecisiveBreak (P9),
// a close through 3+ level highs. MaxList/MinList select between two pivot
// PRICES -- tick-grid operands, the scope their ACCEPTED row allows -- so plain
// comparisons stand in for them here.
//
// Every scratch value is a localVariables entry, never a hook-scope
// declaration, so the hooks survive a double placement.
//
// PIVOT SCAN, hand-rolled in BOTH twins (SwingPivotTarget's open-coded form):
// more than two occurrences are needed and Occurrence 3+ of SwingHigh/SwingLow is
// UNMEASURED, so no SwingHigh(n, ...) call stands in. MEASURED test
// (EL_Swing_Probe.txt / el_swing_output1.txt, @ES 60 min): the pivot bar is AT OR
// BEYOND the `strength` OLDER bars and STRICTLY BEYOND the `strength` NEWER bars
// (bars-ago indexing: the newer bars are the smaller pk, el_gt / el_lt; the older
// el_ge / el_le), confirmation lag exactly `strength` bars, candidate offsets
// strength..window-1, the neighbourhood reaching `strength` bars past the window.
// Swings are non-alternating: highs and lows are two independent series.
// No early break, matching the twin (Break is not a registered word).
//
// WFSafe_AvgTrueRange: MultiWalk's ROLLING accumulator, SwingPointTestHolds's
// block verbatim -- seeded with a full N-term sum on the first calculated bar or
// when the length changes, and after that TWO statements (S += in; S -= out;), because EL
// evaluates S[1] + in - out left to right. It stays in the hook, which the
// generator emits unconditionally.
if (atrLenState != (int)atrLookback) {
    atrSum = 0.0;
    for (aa = 0; aa < (int)atrLookback; ++aa) {
        hiV = high[aa] > close[aa + 1] ? high[aa] : close[aa + 1];
        loV = low[aa] < close[aa + 1] ? low[aa] : close[aa + 1];
        atrSum += hiV - loV;
    }
    atrLenState = (int)atrLookback;
} else {
    outIdx = (int)atrLookback;
    hiV = high[0] > close[1] ? high[0] : close[1];
    loV = low[0] < close[1] ? low[0] : close[1];
    hiO = high[outIdx] > close[outIdx + 1] ? high[outIdx] : close[outIdx + 1];
    loO = low[outIdx] < close[outIdx + 1] ? low[outIdx] : close[outIdx + 1];
    atrSum += hiV - loV;
    atrSum -= hiO - loO;
}
atrValue = atrSum / (int)atrLookback;
pS = (int)strength;
pW = (int)pivotLookback;
nH = 0;
nL = 0;
hb1 = -1;
lb1 = -1;
h1 = 0.0;
h2 = 0.0;
h3 = 0.0;
l1 = 0.0;
l2 = 0.0;
l3 = 0.0;
for (pj = pS; pj <= pW - 1; ++pj) {
    okHi = true;
    okLo = true;
    for (pk = pj - pS; pk < pj; ++pk) {
        if (!el_gt(high[pj], high[pk])) okHi = false;
        if (!el_lt(low[pj], low[pk])) okLo = false;
    }
    for (pk = pj + 1; pk <= pj + pS; ++pk) {
        if (!el_ge(high[pj], high[pk])) okHi = false;
        if (!el_le(low[pj], low[pk])) okLo = false;
    }
    if (okHi && nH < 3) {
        nH = nH + 1;
        if (nH == 1) {
            h1 = high[pj];
            hb1 = pj;
        }
        if (nH == 2) h2 = high[pj];
        if (nH == 3) h3 = high[pj];
    }
    if (okLo && nL < 3) {
        nL = nL + 1;
        if (nL == 1) {
            l1 = low[pj];
            lb1 = pj;
        }
        if (nL == 2) l2 = low[pj];
        if (nL == 3) l3 = low[pj];
    }
}
hTop = h2;
if (h3 > hTop) hTop = h3;
lBot = l2;
if (l3 < lBot) lBot = l3;
